      out="$OUT_ROOT/$base_noext.generated.bin"
      mkdirp "$(dirname "$out")"
      log "cp $t -> $out"
      [[ $DRY -eq 1 ]] || cp -f -- "$t" "$out"
      ;;
  esac
done

